#!/usr/bin/env bash
# Verifies the deployed Arc mainnet contracts against the sources in this directory.
#
#   ./verify.sh sourcify              no credentials required
#   ./verify.sh etherscan             requires ETHERSCAN_API_KEY in the environment (arc.etherscan.io)
#
# Constructor arguments below were recovered from each contract's creation transaction and checked
# against this build's creation code, so nothing here is guessed.
set -euo pipefail
MODE="${1:-sourcify}"
CHAIN=5042
case "$MODE" in
  sourcify)  EXTRA=(--verifier sourcify) ;;
  etherscan) : "${ETHERSCAN_API_KEY:?set ETHERSCAN_API_KEY}"
             # forge ignores --etherscan-api-key for chain ids it does not know; the key must reach it through config.
             export FOUNDRY_ETHERSCAN="{$CHAIN={key=\"$ETHERSCAN_API_KEY\",chain=$CHAIN,url=\"https://api.etherscan.io/v2/api?chainid=$CHAIN\"}}"
             EXTRA=(--verifier etherscan --verifier-url "https://api.etherscan.io/v2/api?chainid=$CHAIN") ;;
  *) echo "usage: $0 sourcify|etherscan" >&2; exit 1 ;;
esac
verify() { echo; echo "== $1  $2"; forge verify-contract "$2" "$3" --chain-id "$CHAIN" --constructor-args "$4" --watch "${EXTRA[@]}"; }

verify v2lockerImpl 0x5853989F172B21Df7fD7714c62dcc48e2DD1E3AE src/ArchemistV2USDCLockerV3.sol:ArchemistV2USDCLockerV3 0x00000000000000000000000000000000000000000000000000000000000013b2
verify v2factoryImpl 0xe93750Affc58792C9a8c78dA84A48C8f0F49de02 src/ArchemistV2USDCFactoryV3.sol:ArchemistV2USDCFactoryV3 0x00000000000000000000000000000000000000000000000000000000000013b2
verify v2lockerProxy 0xD324578C2Caa01Bb454997DFcF531fCB435CE92d src/ArchemistProxy.sol:ArchemistProxy 
verify v2factoryProxy 0x91Aca454C982459899eD46eED9668034Bd7EdF1F src/ArchemistProxy.sol:ArchemistProxy 
